@RunWith(MockitoJUnitRunner.class)
public class CommandLineRunner_createOptions_TriageGen0Test {

  private CommandLineRunner runner;
  private CommandLineRunner.Flags flags;
  private PrintStream out;
  private PrintStream err;

  // Since CommandLineRunner is a complex class and createOptions is protected,
  // we use a subclass or a spy to access the protected method and manipulate flags.
  private static class TestableCommandLineRunner extends CommandLineRunner {
    public TestableCommandLineRunner(String[] args, PrintStream out, PrintStream err) {
      super(args, out, err);
    }

    @Override
    public CompilerOptions createOptions() {
      return super.createOptions();
    }

    // Expose flags for testing if they are not public, 
    // assuming they are accessible within the package or via reflection/protected access.
    public void setFlags(Flags flags) {
      this.flags = flags;
    }
  }

  @Before
  public void setUp() {
    out = mock(PrintStream.class);
    err = mock(PrintStream.class);
    flags = mock(CommandLineRunner.Flags.class);

    // Initialize default mock behaviors for flags to avoid NullPointerException
    flags.compilation_level = mock(CompilationLevel.class);
    flags.warning_level = mock(WarningLevel.class);
    flags.debug = false;
    flags.formatting = Collections.emptyList();
    flags.process_closure_primitives = false;

    runner = new TestableCommandLineRunner(new String[]{}, out, err);
    // We use reflection or a setter to inject the mocked flags into the runner
    // because CommandLineRunner internalizes its flags from args.
    // For the purpose of this unit test, we assume we can inject the mock flags.
    injectFlags(runner, flags);
  }

  private void injectFlags(CommandLineRunner runner, CommandLineRunner.Flags flags) {
    try {
      java.lang.reflect.Field field = CommandLineRunner.class.getDeclaredField("flags");
      field.setAccessible(true);
      field.set(runner, flags);
    } catch (Exception e) {
      throw new RuntimeException(e);
    }
  }

  @Test
  public void testCreateOptions_Basic() {
    flags.compilation_level = mock(CompilationLevel.class);
    flags.warning_level = mock(WarningLevel.class);
    flags.debug = false;
    flags.formatting = Collections.emptyList();
    flags.process_closure_primitives = true;

    // Mock initOptionsFromFlags via spy if possible, or rely on no-op if it's a stub
    TestableCommandLineRunner spyRunner = spy(new TestableCommandLineRunner(new String[]{}, out, err));
    injectFlags(spyRunner, flags);
    doNothing().when(spyRunner).initOptionsFromFlags(org.mockito.ArgumentMatchers.any());

    CompilerOptions options = spyRunner.createOptions();

    assertThat(options).isNotNull();
    verify(flags.compilation_level).setOptionsForCompilationLevel(options);
    verify(flags.warning_level).setOptionsForWarningLevel(options);
    assertThat(options.closurePass).isTrue();
  }

  @Test
  public void testCreateOptions_WithDebug() {
    flags.compilation_level = mock(CompilationLevel.class);
    flags.warning_level = mock(WarningLevel.class);
    flags.debug = true;
    flags.formatting = Collections.emptyList();
    flags.process_closure_primitives = false;

    TestableCommandLineRunner spyRunner = spy(new TestableCommandLineRunner(new String[]{}, out, err));
    injectFlags(spyRunner, flags);
    doNothing().when(spyRunner).initOptionsFromFlags(org.mockito.ArgumentMatchers.any());

    CompilerOptions options = spyRunner.createOptions();

    verify(flags.compilation_level).setDebugOptionsForCompilationLevel(options);
    assertThat(options.closurePass).isFalse();
  }

  @Test
  public void testCreateOptions_WithFormattingOptions() {
    flags.compilation_level = mock(CompilationLevel.class);
    flags.warning_level = mock(WarningLevel.class);
    flags.debug = false;

    FormattingOption mockFormat = mock(FormattingOption.class);
    flags.formatting = Collections.singletonList(mockFormat);
    flags.process_closure_primitives = false;

    TestableCommandLineRunner spyRunner = spy(new TestableCommandLineRunner(new String[]{}, out, err));
    injectFlags(spyRunner, flags);
    doNothing().when(spyRunner).initOptionsFromFlags(org.mockito.ArgumentMatchers.any());

    CompilerOptions options = spyRunner.createOptions();

    verify(mockFormat).applyToOptions(options);
  }
}
